CREATE TABLE skill_catalog_entries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL CHECK(btrim(name) <> ''), version TEXT NOT NULL CHECK(btrim(version) <> ''), description TEXT NOT NULL, content TEXT NOT NULL CHECK(length(content) BETWEEN 1 AND 32000), content_hash TEXT NOT NULL CHECK(length(content_hash)=64), status TEXT NOT NULL CHECK(status IN ('draft','approved','disabled')), reviewed_by_user_id INTEGER REFERENCES users(id), reviewed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(owner_user_id,name,version), CHECK(status <> 'approved' OR reviewed_by_user_id IS NOT NULL));
ALTER TABLE bear_skills_manifest ADD COLUMN catalog_entry_id UUID REFERENCES skill_catalog_entries(id), ADD COLUMN enabled BOOLEAN NOT NULL DEFAULT false, ADD COLUMN attached_by_user_id INTEGER REFERENCES users(id);
ALTER TABLE bear_skill_proposals ADD COLUMN proposed_by_user_id INTEGER REFERENCES users(id), ADD COLUMN reviewed_by_user_id INTEGER REFERENCES users(id);
CREATE INDEX bear_skills_catalog_entry ON bear_skills_manifest(catalog_entry_id);
